// EN stigma set/piece OR EX-weapon name -> official ZH {name, desc} (Inheritance)
export const HW_ZH_INHERITANCE = {
  "Abyss": { name: "深渊", desc: "诞生于地狱深渊的诅咒象征。低语著永恒的痛苦与绝望，吞噬罪恶，并将凡人拖入无尽的黑暗之中。" },
  "Aerial Acrobatics": { name: "空中杂技", desc: "世人嘲笑又何妨！这世界嘲笑我，不如自由地活着。" },
  "Arcane Flow": { name: "魔力之流", desc: "纯粹而原始的基础技巧，是踏上更高阶梯的基石。" },
  "Aronbite": { name: "亚隆拜特", desc: "绝不断裂，也绝不缺口——以坚不可摧闻名的格里克族传说名剑「亚隆拜特」，象征著他们不屈不挠的信念，也因此仅有最具荣耀的君主才被允许拥有。 根据无从考证的古老传说，这把剑是伟大的格里克骑士燃烧自己的灵魂锻造而成，据说能为持有者带来永恒的胜利。事实也仿佛印证了这一点——亚隆拜特的历代主人皆以高贵与强大之姿，缔造了无与伦比的声望。" },
  "Artist's Comedia": { name: "艺术家的戏曲", desc: "艺术家有四类：夸张者、信仰者、妄想者和悔悟者。" },
  "Atra-hasis": { name: "阿特拉哈西斯", desc: "提及于特拉内尔建国神话中的圣物，也是仅限公国最伟大的流动守护者所能触及的象征物。与其他普通象征物不同的是，阿特拉哈西斯能够与操纵流动的魔法力量产生共鸣。在适格主人的手中，这根法杖甚至能够强迫最狂暴的洋流化为无波的平静，反之亦然。" },
  "Barbed Tongue": { name: "荆棘之辩", desc: "他从未向人敞开心扉，直到遇见了温柔的她。" },
  "Bitter Resolve": { name: "卧薪尝胆", desc: "十年耻辱只为一战雪耻，磨骨削肉为之。" },
  "Blade of the Sun": { name: "太阳之日", desc: "即使是自行绽放光芒的太阳，起初也必然微弱。深知此理的小小火种静静燃烧著，等待著终将到来的炽烈之时。" },
  "Blazing Forge": { name: "燃烧的熔炉", desc: "成为匠人的方法很简单，坚持做自己喜欢的事。" },
  "Blessed Cat Bell": { name: "祝福的猫铃", desc: "在广阔宇宙中，智慧体对猫的爱意，强烈而真挚到足以孕育出一位猫神。于是那位慵懒、睿智又可爱的猫神便有了这样的想法：爱，不该只是接受，也该懂得分享。其结果，便是那些散落于宇宙各处、极为稀有的「猫神之铃」。这件强大的道具，以各式各样的铃铛形态出现，据说会现身于真心爱猫之人面前，为他们带来幸运。若你真切怀抱著对猫的爱、并始终守护那份心意，那么，猫神所赐予的幸运或许就会在你眼前现形。" },
  "Boreas the Slicer": { name: "割裂肌肤的北风", desc: "随风而行，小至种子，大至黑烟。" },
  "Breath of the Wind": { name: "风之呢喃", desc: "构成世界的四种物质，一切皆趋于调和。" },
  "Chaser": { name: "追击者", desc: "追逐猎物时，从树间擦过长长的血迹。" },
  "Chrysaor": { name: "克律萨俄耳", desc: "克律萨俄耳，同样是仅传承给守护白金枝王国高洁之王、最贴身近卫骑士的两把古代双刃剑之一。如同高原精灵那遥远悠久的历史一般，这也是一件难以推测其起源的武具，但即便到了现代，依旧拥有宛如艺术品般闪耀的光芒，以及丝毫不曾锈蚀的锋芒。那宛若花苞般的剑尖，比想像中还不锋利，而据说这是因为此武器真正的力量，源自于使用者与生俱来的魔力。「克律萨俄耳」也是一种代号。原本指称这件武具的古代语，因人类难以发音，故在获得使用者同意后，改以地球神话中的词语重新命名。据说，这件武具原本的精灵语名称，其意为——「苍穹的锐利轨迹」。" },
  "Cleric's Scripture": { name: "圣职者的经书", desc: "艺术家有四类：夸张者、信仰者、妄想者和悔悟者。" },
  "Crimson Veil Torturas": { name: "赤霜托尔图拉斯", desc: "这是托尔塔部族一位隐士留给其女儿的唯一遗产——一柄于雪山深夜中锻造的双刃巨剑。双刃以粗犷的陨石钢铸成，刀身上浮现着被称为「咆哮水晶」的红色刻印。根据裂缝局的结构分析，那是一种在无数雪战后，由氧化铁在魔力作用下觉醒而成的特殊结晶。虽然此剑的起源尚不明确，但据说在托尔塔利亚最原始的神话中，也曾提及过这般血红而野性的刀刃。" },
  "Cycle of Sin": { name: "罪恶的枷锁", desc: "欲望燃烧一切生灵，直至其化为虚无。" },
  "DMP-9 Prototype": { name: "DMP-9 原型", desc: "被称为裂缝局科技科的杰作与不可思议存在的 DMP-9 原型，虽然完美展现了裂缝局武器设计所追求的简洁与单纯之美，但其中隐含的故事与难以理解的火力，却远非如此单纯。因为连裂缝局的技术者们都无法弄清，这具性能远超常规水准的 DMP-9 原型机究竟是以什么原理展现出如此惊人的威能——甚至明明是他们自己所制造出来的！也正因如此，担心会亲手破坏这件杰作的裂缝局科技科，根本不敢选择将 DMP-9 原型拆解分析。最终，由于裂缝局放弃了量产计划，这把传说般的武器只能如其名一般，永远停留在「原型」的状态。然而它在战场上所展现出的惊人火力，却无庸置疑。" },
  "Dawnbringer": { name: "黎明引导者", desc: "战场上最深的静寂，如同破晓前的黑暗。众人屏息，彼此对峙，却无人敢率先迈出那一步。而这把剑，正是打破那份沉默的第一声呼喊，也是划开凝固战线的第一道光。持剑之人，总是最先立于前线，亲身证明——黎明，并非等待而来，而是以剑锋开拓而成。" },
  "Diary of the Premature One": { name: "早熟青年的日记", desc: "艺术家有四类：夸张者、信仰者、妄想者和悔悟者。" },
  "Doomstar": { name: "死亡之星", desc: "起初，它只是一根装有钉刺铁球的金属球棒，但随著一次次生死交关的战斗，越来越多碎片与金属被加装上去，有时甚至直接把废铁敲进其中。如今，它早已变成一把难以再称作球棒的怪物级武器。它可以用来砸碎、切割、整理庭院、刺击、贯穿，甚至撬开箱子，但最致命的用法，还是将它沉重地一挥，把这一切一次全部施加到对手身上。" },
  "Elder's Memoir": { name: "老人的回忆录", desc: "艺术家有四类：夸张者、信仰者、妄想者和悔悟者。" },
  "Eleuthia": { name: "埃雷乌缇亚", desc: "埃雷乌缇亚，是仅传承给守护白金枝王国高洁之王、最贴身近卫骑士的两把古代双刃剑之一。如同高原精灵那悠远漫长的历史一般，这是一件难以追溯其起源的武具，但即使到了现代，依旧散发著宛如艺术品般美丽的光辉，以及毫无锈蚀的锋利。根据传承，它象征著一位同时持有盾与弓的古代精灵英雄。「埃雷乌缇亚」其实是一种代号。原本用来称呼这件武具的古代语，对人类而言难以发音，因此在获得使用者许可后，才以地球神话中的词语重新命名。据说，这件武具原本的精灵语名称，其意为——「星群的金色帷幕」。" },
  "Empty Chest": { name: "空荡的箱子", desc: "欲望燃烧一切生灵，直至其化为虚无。" },
  "End of Greed": { name: "贪欲的结局", desc: "欲望燃烧一切生灵，直至其化为虚无。" },
  "Endless Burger": { name: "怎么吃都吃不完的汉堡", desc: "这种无论怎么吃都不会减少的食物，或许是能够永远解决人类饥饿与饥荒的梦幻物质。然而可惜的是，这个物品的本质与这样的理想相去甚远。虽然它拥有理想汉堡的外型与口感，但这个「魔力球」的真面目，其实更接近于包裹著中央漆黑碎片的魔力凝聚体。因此，它的主要功能只是在优秀口感的加持下提振术士的精神。而且吃得越多体重还会增加，完全没有减肥效果。不过，作为能套用于生命力的高级魔力球，其性能属于最顶级。如果能抵挡住美味气味的诱惑，或者干脆不在乎身材的术士，这东西作为武器也是不错的选择。" },
  "Essence of Life": { name: "生命的精髓", desc: "以冰冷宇宙的温度加以温暖的，唯有奔驰于生命之中的存在…" },
  "Europa": { name: "欧罗巴", desc: "在统御天空的神明之名下，一切皆遵循雷霆的法则。" },
  "Eurus the Reaper": { name: "收割灵魂的东风", desc: "随风而行，小至种子，大至黑烟。" },
  "Fighter's Courage": { name: "战士的勇气", desc: "以勇气开始的战斗化为自豪，以斗志开始的战斗化为顽强。" },
  "Fighter's Determination": { name: "战士的斗志", desc: "以勇气开始的战斗化为自豪，以斗志开始的战斗化为顽强。" },
  "Fighter's Pride": { name: "战士的自豪", desc: "以勇气开始的战斗化为自豪，以斗志开始的战斗化为顽强。" },
  "Fighter's Resilience": { name: "战士的顽强", desc: "以勇气开始的战斗化为自豪，以斗志开始的战斗化为顽强。" },
  "Fleure de Vanite 92": { name: "浮华之花 92", desc: "镶嵌着神秘诅咒的两把豪华武器‘浮华之花’，其奢华的外形包裹着复杂的符文。这些符文是裂缝管理局尝试用科学解释魔法过程中开发出的成果，用于封印诅咒的装置被刻在金属基底之上。」\n据传，这种武器的原型已经几乎无法辨认，但其诅咒功能依然强大。这些武器从证物保管所被送至研究室，原计划移交博物馆，但却因其华丽外观被情报科的一位科长悄悄据为己有。" },
  "Flow of Life": { name: "生命的流动", desc: "以冰冷宇宙的温度加以温暖的，唯有奔驰于生命之中的存在…" },
  "Ganymede": { name: "伽倪墨得斯", desc: "在统御天空的神明之名下，一切皆遵循雷霆的法则。" },
  "Gehenna": { name: "地狱谷", desc: "诞生于地狱深渊的诅咒象征。低语著永恒的痛苦与绝望，吞噬罪恶，并将凡人拖入无尽的黑暗之中。" },
  "Harvest of Dawn": { name: "黎明的果实", desc: "黎明不是祝福。那是只会赐予「忍过黑暗之人」的约定。" },
  "Hawkeye": { name: "鹰眼", desc: "追逐猎物时，从树间擦过长长的血迹。" },
  "Heart with Broken Thorns": { name: "充满折断荆棘的心", desc: "他从未向人敞开心扉，直到遇见了温柔的她。" },
  "Indomitable": { name: "百折不屈", desc: "十年耻辱只为一战雪耻，磨骨削肉为之。" },
  "Io": { name: "伊娥", desc: "在统御天空的神明之名下，一切皆遵循雷霆的法则。" },
  "JK220 Artemis": { name: "JK220 阿尔忒弥斯", desc: "面向模型的杰作JK220阿尔忒弥斯是尖端科技与精密设计的结晶，为裂缝管理局的顶级狙击手量身定制。这款武器拥有卓越的杀伤力，枪管配备最新的军用软件‘阿尔忒弥斯’，使用户能够更有效地躲避敌人的视线。 JK220的名字用以致敬裂缝管理局最优秀的狙击手。" },
  "Jester's Delusion": { name: "小丑的妄想", desc: "诞生于地狱深渊的诅咒象征。低语著永恒的痛苦与绝望，吞噬罪恶，并将凡人拖入无尽的黑暗之中。" },
  "Jester's Hallucination": { name: "小丑的幻觉", desc: "那是藏于强大存在面具之下，由破碎情感所凝聚而成的力量结晶。这些在虚妄之梦中迷失的情绪残渣，对大多数生命而言极为危险，但对真正卓越的魔法师来说，或许正是迈向更强之力的契机。" },
  "Jester's Jealousy": { name: "小丑的嫉妒", desc: "那是藏于强大存在面具之下，由破碎情感所凝聚而成的力量结晶。这些在虚妄之梦中迷失的情绪残渣，对大多数生命而言极为危险，但对真正卓越的魔法师来说，或许正是迈向更强之力的契机。" },
  "Jester's Spite": { name: "小丑的憎恶", desc: "那是藏于强大存在面具之下，由破碎情感所凝聚而成的力量结晶。这些在虚妄之梦中迷失的情绪残渣，对大多数生命而言极为危险，但对真正卓越的魔法师来说，或许正是迈向更强之力的契机。" },
  "Kaiserstolz": { name: "自豪", desc: "帝国的宝物「自豪」，正如其名，是帝国的骄傲。当帝国还只是一个跨越世界而来的小小移民群体的时代，初代皇帝仅凭一柄长剑与一面盾牌，便书写下传奇。初代皇帝的伟业正是如此诞生。击退威胁帝国的敌人，守护因恐惧而颤抖的百姓。自此，帝国的敌人开始畏惧那被称为「自豪」的剑与盾，而这份恐惧也成为奠定帝国这座巨山基础的力量。这件缔造伟大帝国的传说武器，之后被奉为帝国的至宝流传下来。它以不变的象征性与被强大魔法强化的力量而声名远扬… 然而，世间万事终有起伏。在席卷诺克提斯星的裂缝灾变混乱之中，「自豪」也不知消失于何处。即便如此，帝国的子民仍然记得它那闪耀的身姿，并心怀期盼——期盼那曾与帝国历史一同开启的「自豪」能够再次归来，为离开故乡的人们重新带来希望，并以那份力量守护他们。" },
  "Lamoran Spiraldrive": { name: "拉莫拉加速器", desc: "以不明的古代拉莫拉遗物作为动力源，自行旋转并贯穿、粉碎敌人的这件巨大武器，是拉莫拉行星上众多神秘武器之一。最重要的是，这个由拉莫拉人武器扭曲构成外观的庞然之物，天生就为破坏与粉碎目标而存在。这件以无法穷尽的力量不断旋转的沉重巨兵，不仅拥有单纯的破坏力，还具备将其力量分与使用者，使其动作更为迅捷、视野更加敏锐的神秘特性。正因如此，也有人认为拉莫拉加速器比起伤害他人，更适合用于守护，甚至或许是出于父母爱护孩子的心意而诞生的武器。然而，光是那凶恶的外观，以及战斗后留下的更为毁灭性的痕迹，便足以让人明白这种说法终究只是玩笑——这也可说是世间的普遍看法。" },
  "Last Stand": { name: "背水一战", desc: "十年耻辱只为一战雪耻，磨骨削肉为之。" },
  "Lumen Veritas": { name: "真理之光", desc: "转换术士集团王冠探究者，凭借悠久的历史，持有多件令人惊叹的奇物。而其中对外最为知名的，便是据说蕴含历代至尊全部力量的「真理之光」，那是王冠探究者的领袖象征。走向死亡的至尊们，为了王冠探究者的延续，将自己毕生累积的所有力量灌注进真理之光之中；而后继的至尊，则凭借那其中所蕴藏的力量，与王冠探究者的敌人对抗至今。然而，王冠探究者的根据地——变化的城塞，终究未能战胜席卷诺克提斯星的裂缝事态而崩毁；王冠探究者本身也在近乎瓦解的动荡之中分崩离析，真理之光亦随之下落不明… 只是，若思及那股强大力量所将牵引的命运，这场失踪，恐怕不会持续太久。" },
  "Magic Show": { name: "魔术表演", desc: "世人嘲笑又何妨！这世界嘲笑我，不如自由地活着。" },
  "Marksman's Agility": { name: "射手的敏捷", desc: "射手的实力在于捕捉目标、装填弹药并发射的时机。" },
  "Marksman's Caution": { name: "射手的谨慎", desc: "射手的实力在于捕捉目标、装填弹药并发射的时机。" },
  "Marksman's Composure": { name: "射手的冷静", desc: "射手的实力在于捕捉目标、装填弹药并发射的时机。" },
  "Marksman's Precision": { name: "射手的准确", desc: "射手的实力在于捕捉目标、装填弹药并发射的时机。" },
  "Massively Vibrating Pole": { name: "超屌震动巨柱剑", desc: "如今已无法得知这究竟出自哪位伟大的凯萨克之手，但光是望上一眼，就能感受到那份压迫感。这件成人玩具如今被愚钝的凯萨克后裔们，当作极佳的武器使用。以强烈的震动功能与毫不弯折的坚固材质为傲，经历无数次摩擦与碰撞后，终于在一侧磨出微薄刃口的这把古代凯萨克之具，正完美契合了凯萨克「摧毁与碾碎」的嗜好。因此，它成为全凯萨克族梦寐以求的美丽武器。被这柄巨大震动剑击中的敌人，往往还来不及感受到愤怒，便在痛苦中翻滚，以肉身深刻体验——伟大的古代凯萨克科学力。" },
  "Mended Plank": { name: "裂开后修补的木板", desc: "一块块修补而成的船帆已不见原貌。" },
  "Nocturnal Watcher": { name: "夜之监视者", desc: "潜伏于黑暗中的「夜之监视者」，对新首尔的恶棍们而言，是恐惧的代名词。夜之监视者所怀抱的毒素，对那些觊觎无辜之人财产与性命的恶徒从不手软。贫民窟里的坏人们，一想到那能夺命的利刃，便不禁陷入惊惧。在漆黑的夜晚，凡是企图加害无辜的预备犯人，都该好好思量，夜之监视者的刀锋是否已悄然逼近自己咽喉。" },
  "Notus the Stormer": { name: "召来风雨的南风", desc: "随风而行，小至种子，大至黑烟。" },
  "Oath of Dawn": { name: "黎明的誓约", desc: "黎明不是祝福。那是只会赐予「忍过黑暗之人」的约定。" },
  "Oath of Life": { name: "生命的誓约", desc: "以冰冷宇宙的温度加以温暖的，唯有奔驰于生命之中的存在…" },
  "Ofuda: Fox Spirit's Guidance": { name: "护符：狐神的引导", desc: "一名巫女依照狐狸神社代代相传的护符制作法，为新的神明亲手制成的护符。原本，狐狸神社的护符是为了引导亡者，并对付那些企图袭击亡者的恶鬼而制作。如今，却成了某位巫女为新神倾注百分之百私心打造的万能型咒具。由于制作这张护符的巫女欲望过于强烈，护符除了原有用途之外，还寄宿著「鸿运当头、万事亨通、姻缘顺遂、学业有成、厄运消散、心愿成真！」等各式各样的灵验功效。即使只是由普通人持有，也足以阻挡无名杂灵与程度较轻的厄运。这张护符承载著巫女思念神明的心意，由她倾注心血精心制成。其作为咒具的性能，已达到绝对不容小觑的程度；对神明的信仰越是虔诚，其力量便会变得越强。尽管这是巫女赤裸裸的欲望所催生的产物，她对神明近乎盲目的信仰却与之产生了相乘效果，最终造就出令人惊叹的灵验之力。" },
  "Orbina": { name: "奥尔比娜", desc: "据说会自行选择最适合自己的魔法师的这根法杖，被认为是远古时期，由诺克提斯星的巨型建筑者们将大地与星辰之力编织成设计图时所留下的遗产。这根法杖既是运算设计图的工具，也是能与大地与星辰核心所蕴含的固有力量产生共鸣，从而构筑时空的媒介。有人说它曾被用于建造帝国的不可思议之伟业，也有人认为它不过只是单纯的运算辅助工具。然而唯一可以确定的是，这根法杖的力量并非对任何人都开放。唯有能够掌控大地与时空流动的极少数优秀魔法师，才能真正引出它的力量；至于其他人而言，它只是一根带有些许沉重与陌生力量的魔法杖罢了。" },
  "Patched Sail": { name: "缝补的风帆", desc: "一块块修补而成的船帆已不见原貌。" },
  "Phantom Stiletto": { name: "精密之锥", desc: "长年锻炼念动力的超能力者的意志，早已深深烙印于武器之中。那支原本平凡无奇的手枪，如今能与使用者的灵魂感应，将子弹如尖锥般准确刺入目标。它不仅能回应主人对胜利与生存的执念，展现出惊人的力量，甚至能感应到并共鸣于同伴们的精神。这把令人惊叹的武器，无疑是为了完成任务而诞生的最佳工具。\n敌人——将无处可逃。" },
  "Poise and Tranquility": { name: "冷静与沉着", desc: "追逐猎物时，从树间擦过长长的血迹。" },
  "Price of Choice": { name: "选择的代价", desc: "欲望燃烧一切生灵，直至其化为虚无。" },
  "Pulse of the Earth": { name: "大地脉动", desc: "构成世界的四种物质，一切皆趋于调和。" },
  "Pure Strength": { name: "纯净的力量", desc: "纯粹而原始的基础技巧，是踏上更高阶梯的基石。" },
  "Purgatory": { name: "炼狱", desc: "诞生于地狱深渊的诅咒象征。低语著永恒的痛苦与绝望，吞噬罪恶，并将凡人拖入无尽的黑暗之中。" },
  "Ray of Dawn": { name: "黎明的光芒", desc: "黎明不是祝福。那是只会赐予「忍过黑暗之人」的约定。" },
  "Rebuilt Hull": { name: "破损后重新修复的船体", desc: "一块块修补而成的船帆已不见原貌。" },
  "Red Pudding": { name: "红色布丁", desc: "古代的凯萨克人曾把这作为医疗器械挽救生命，但愚昧的后代们却更专注于争战，而非拯救他人。此器原本的制造目的，是为急救患者生成高级人工血液并用于输血的医疗装置，然而失落了古老知识的现代凯萨克人，几乎极少将其用回原本用途。然而，若是觉醒了生命之流的人能将此法杖握于手中，或许便能发挥出真正的力量。" },
  "Renewed Prow": { name: "损坏后更换的船首", desc: "一块块修补而成的船帆已不见原貌。" },
  "Ruthless Assault": { name: "无情的攻击", desc: "追逐猎物时，从树间擦过长长的血迹。" },
  "Ruthless Judgment": { name: "冷酷的处决", desc: "斗争是残酷的，却也正因如此而美丽。枪械原本只是为了取得战略与战术优势而诞生，只不过是为了杀人而打造的工具。然而不知从何时开始，它与冰冷的死亡紧密相连，逐渐孕育出独有的魅惑性。这一点，在崇尚强大的军国主义社会——奥尔克亦是如此。或许正因他们歌颂战争之美，才会理所当然地希望自己手中的武器也同样美丽。奥尔克的工匠们认为，枪械并不只是单纯的武器，而是超越武器的艺术品，是他们倾注一生所打造出的作品。而这份作品性，便存在于动用一切可用手段的极致追求之中。其中最为出色的少数作品，更在魔力与技术的交织之下孕育出令人惊叹的力量。就这样诞生的奥尔克工匠枪械，往往拥有超越一般物理法则的性能，以及光是看上一眼便能夺走视线的美学魅力，危险而耀眼地闪烁著。" },
  "SS4 – Refitted Model": { name: "SS4-修改型", desc: "原本为最顶尖的 Discover 特工打造的原型步枪，经由金佳映再次改造升级。她一如既往地缜密周到，为了能应对各种情况与任何敌人，替步枪加装了多种附件。虽然因此比预想中还要庞大不少，但也正因她的满备准备，使这把武器能在任何战况下都发挥最佳性能。" },
  "Sacrament of Mercy": { name: "慈悲誓约", desc: "源于分枝女神、蕴含祝福的巫具。其本体原为雕刻有女神圣像的神圣祭坛的一部分，为了应对教会所面临的危机，最终被改造为战斗武器。虽然一开始有意见认为这是亵渎神明的行为，但随著女神透过神谕亲自允许，争议也随之平息。（据记载——女神在「自己的圣像击碎恶魔的头骨」的瞬间显得非常欢喜。）令人联想到先进科学的盾牌原理其实就是依赖神圣力。实际上，大祭司们用这巫具克服了无数危机，也因此逐渐赋予其更强大的神圣性能。据说，当这件巫具交到「化身圣女」之手时，将能发挥出最强的力量。" },
  "Sacred Flame": { name: "神圣之火", desc: "即使是自行绽放光芒的太阳，起初也必然微弱。深知此理的小小火种静静燃烧著，等待著终将到来的炽烈之时。" },
  "Scales of Blight": { name: "褪色天秤", desc: "将使用者的愿望转化为毒之力量的这件魔法器物，源自宇宙为了维系世界平衡而诞生的意志。诞生于生与死交界处的这座神秘魔法天秤，虽然蕴藏著足以毁灭一切的可怕可能性，但若落入合适之人的手中，或许也能成为救赎的另一个名字。" },
  "Seryel: Medical Hammer": { name: "赛里欧尔：医疗锤", desc: "这件工具的本来用途，是为了在野战中快速检测生体讯号，并测量神圣力反应而制作的先进医疗装备。然而，由于初期裂缝局技术工学部部分成员过度的热情，这件装备的内部骨架被加强得远超所需，并以极度精密、平衡良好的形式完成。其结果便是——这个小小的诊疗器具在成为精密检诊器之前，就先成为一件拥有完美硬度与平衡性的强力钝器兼防具。最终，除了少数特别人士外，几乎无法再作为医疗用途使用，但光是内建的战斗辅助功能，就足以让它作为武器拥有极高价值。" },
  "Shining Gemstone": { name: "闪耀的原石", desc: "成为匠人的方法很简单，坚持做自己喜欢的事。" },
  "Skadia": { name: "斯卡迪亚", desc: "斯卡迪亚是一根以冰晶纯净美丽形态为原型打造的法杖，曾在伟大的霜术士手中大放异彩的传奇兵器。每一处边缘都蕴含着寒冷且强大的魔力，据说能凭使用者的意志冻结视线所及之处。尽管霜术士在战场上展现了压倒性的力量，但由于其仅专注于操控霜之魔法，斯卡迪亚和霜术士最终未能获得胜利的荣耀，最终湮没于历史的尘埃中。" },
  "Sol": { name: "索尔", desc: "索尔是一根蕴含太阳最炽热火焰之力的法杖。它在皇室中世代相传，杖尖镶嵌着一颗日耀石，使持有者能够随心所欲地操控火焰。\n\n每一次挥舞，索尔的火焰都会将敌人吞噬在炽热的怀抱中，据说这种火焰只有在太阳熄灭的那一天才会消散。" },
  "Song of the Flames": { name: "烈焰之歌", desc: "构成世界的四种物质，一切皆趋于调和。" },
  "Spear of Sunlight": { name: "日光之枪", desc: "即使是自行绽放光芒的太阳，起初也必然微弱。深知此理的小小火种静静燃烧著，等待著终将到来的炽烈之时。" },
  "Stand-up Comedy": { name: "插科打诨", desc: "世人嘲笑又何妨！这世界嘲笑我，不如自由地活着。" },
  "Star Splicer": { name: "斩星剑", desc: "斩裂苍穹的传说之剑—— 斩星剑，正如其名，传闻连星辰都能一分为二。剑锋上蕴藏的强大力量，能瞬间斩断任何物质，而握持此剑者，将成为战场的支配者。一剑挥出，连痕迹都不会留下，在其锋芒之下，时间与空间皆会裂开。然而，唯有玛格纳尔的剑圣，才能真正释放这柄剑的全部力量。" },
  "Storm's Eye": { name: "风暴之眼", desc: "无人知晓这件遗物自何时起，成为令凯萨克英雄们毛骨悚然的存在，但有一点毋庸置疑——凡是垂涎此强大遗物之人，无一不走向毁灭。由于历任持有者的行踪总是成谜，「风暴之眼」在凯萨克的天空盗贼之间，被视为既令人恐惧又充满诱惑魅力的危险宝物。而在某日，「风暴之眼」忽然消失得无影无踪，但至今仍有许多凯萨克人，追寻著这曾散发强大而美丽光芒的武器下落。" },
  "Tartarus": { name: "塔尔塔罗斯", desc: "诞生于地狱深渊的诅咒象征。低语著永恒的痛苦与绝望，吞噬罪恶，并将凡人拖入无尽的黑暗之中。" },
  "The Aegaeon Core": { name: "艾盖翁核心", desc: "据说设计于过去的黄金时代的高级核心。即使投入现代最高技术，也难以轻易完成的精密工艺使其臭名昭著。\n卓越的性能能够最大限度地发挥所搭载的自主兵器的性能，不仅能提升防御功能，还能提供额外的应对能力。\n这种性能特别适用于破坏战车型号，若搭载于高级型号，更能发挥压制敌方目标攻击性能的效果。" },
  "The Anguished Rose": { name: "悲恋之玫瑰", desc: "这是在特拉内尔常见的秘法球，外形酷似特拉内尔玫瑰。据古老的传说，风之花瓣塔中曾有一件被推荐给不擅长解读魔力流动的风术师们的特殊遗物。这件风向仪呈花蕾形状，能够响应使用者的魔力，指引其前进的方向。有一天，这件被称为「悲恋之玫瑰」的风向仪落入了一位迷失归途的风术师手中，平静地引导着她混乱的心。据说她消失在风向仪所指引的方向，仿佛跳舞般离去，只留下人们关于其「太过美丽」或「令人心碎」的传闻。" },
  "The Arms of Laphnesis": { name: "拉夫涅西斯的武具", desc: "拉莫拉士兵所使用的标准化光束系战斗装备，其中该型号尤其以卓越的防御与攻击性能而闻名。\n这款拉夫涅西斯型号的性能得到了飞跃性的提升，以至于因其过于超前，不适合普通士兵使用，而长期受到生产限制。\n此武器能够强化佩戴者的「胜利意志」，不仅能整备前线战斗力，还能根据使用者的能力提升友军部队的战斗效率。" },
  "The Black Horseman of Famine": { name: "饥荒的黑骑士", desc: "四骑士将至，他们游历诸多世界，但不被欢迎。" },
  "The Black Idol": { name: "黑色偶像", desc: "用某人的毛发制作的束缚物。从外表看似普通，但内部蕴含强大的神圣力量。粗壮结实的毛发象征着主人的健康和生命力，并能对信仰和渴望作出反应，大幅增强使用者的魔力。据说这件神器原本是裂缝管理局的一位妖精为出售而收集的，最终落入了最渴求它的人手中。" },
  "The Bloody Acacia": { name: "血红相伴的金合欢", desc: "一把带有荆棘装饰的花剑。这件武器是为了纪念某位恶魔几乎摧毁「希琳娜修女骑士团」的屈辱事件而制作的。剑刃的纹饰象征希琳娜教团的教义，荆棘藤蔓象征恶魔的侵袭，而末端的血色则代表对恶魔的惩罚。由于剑身融入了恶魔的身体部位，传说合法持有者可以让剑的形态发生变化。如果持有者渴望通过鲜血进行训诫，这把「血红相伴的金合欢」将乐意响应持有者的意愿。" },
  "The Blue Horseman of Death": { name: "死亡的青骑士", desc: "四骑士将至，他们游历诸多世界，但不被欢迎。" },
  "The Brilliant Dream in Green": { name: "灿烂的翠绿梦", desc: "神秘的森林深处，盛开的妖精故事。" },
  "The Brilliant Gift of Nature": { name: "灿烂的自然馈赠", desc: "神秘的森林深处，盛开的妖精故事。" },
  "The Brilliant Harmony of Elementals": { name: "灿烂的精灵和谐", desc: "神秘的森林深处，盛开的妖精故事。" },
  "The Brilliant Symphony of Fairies": { name: "灿烂的妖精交响曲", desc: "神秘的森林深处，盛开的妖精故事。" },
  "The Cranium of the Defeated": { name: "败者之首", desc: "这是一个形似骑士头颅的零件，内部燃烧着不祥的蓝色火焰。最初设计为具有威压感的护手和配备厚重铠甲的头盔，但最终被制作为秘法球。每个组件都以裂缝管理局的科学技术结合魔力锻造而成，具备极高的硬度。除了内部储存的魔力外，它还能捕捉漂浮的怨念并将其植入使用者的内心。然而，据推测，能够真正发挥这件物品全部力量的所有者极为稀少。" },
  "The Crimson Executioner": { name: "血色处刑者", desc: "血色处刑者是一种非常著名的暗杀工具。然而，「暗杀」与「著名」这两个词似乎矛盾，但这款暗杀工具却让两者完美结合，其原因在于，它的记录更接近于大规模屠杀而非隐秘的暗杀。这种工具的制作理念是为了迎合某位粗暴的凯特希刺客的信条：如果没有目击者，就不算暗杀。由于过于频繁的屠杀，这把武器吸饱了鲜血，散发着令人作呕的血腥气味，无法抹去。" },
  "The Eternal Champion of Valor": { name: "永恒的勇猛战士", desc: "永恒并非由勇气与荣耀构成，而是由血染的砖石堆砌而成。" },
  "The Eternal Crown of Glory": { name: "永恒的荣耀花冠", desc: "永恒并非由勇气与荣耀构成，而是由血染的砖石堆砌而成。" },
  "The Eternal Howl of Blood": { name: "永恒的血之哀鸣", desc: "永恒并非由勇气与荣耀构成，而是由血染的砖石堆砌而成。" },
  "The Eternal Weapon of Ancient": { name: "永恒的古代武器", desc: "永恒并非由勇气与荣耀构成，而是由血染的砖石堆砌而成。" },
  "The Eye of Cosmos": { name: "掌中宇宙", desc: "掌中宇宙是一种蕴含无限可能的小型秘法球。使用者握住这颗球并施展奇迹时，过去与未来的界限被打破，无数结果的碎片透过现实的缝隙浮现。球体中闪烁的星光象征着命运的诸多面向，而这件辉煌的工具会根据使用者的选择将其中之一确定下来。是祝福还是灾厄，只有握住球的人才能知晓。" },
  "The Farseer": { name: "远见的先知", desc: "久远的过去，传说中的四个男人的故事。" },
  "The Fire Thief": { name: "偷取火焰的小偷", desc: "久远的过去，传说中的四个男人的故事。" },
  "The First Heart": { name: "第一颗心脏", desc: "第一代人神亲手制作并赠送给其护卫的魔核。作为高贵纯洁的守护意志的集合体，这颗魔核赋予共鸣的守护者坚不可摧的意志以及与之匹配的魔力。" },
  "The Grand Ancestor's Spirit": { name: "伟大先祖的圣痕", desc: "拥有古代形态的托尔图拉斯，与普通的托尔图拉斯有着截然不同的独特外形。这把武器蕴含着远古的力量，唯有被选中的托尔塔大战士才能挥舞。它的力量不仅仅局限于物理层面，更与先祖的灵魂相连，使得大战士能够发挥出更为强大的力量。被选中的大战士可以感受到古代战士们的记忆，并从中汲取他们的智慧与勇气，与敌人奋战。" },
  "The Lamoran Wind": { name: "拉莫拉之风", desc: "拉莫拉的剑术极为独特。通过尖端技术严密分析和精确计算，他们的剑术以无多余动作的剑路完美刺穿并切割敌人最脆弱的部位。而在这些剑术大师中，达到极限的剑士甚至无需顾及剑的耐久性。「拉莫拉之风」正是为他们而打造的剑。它的锋刃锐利到肉眼几乎看不见，仅凭这一点便已足够。" },
  "The Ninth Bite": { name: "第九毒牙", desc: "这是一种由卡特里亚历史上最可怕的灾难之一——怪物的第九颗头颅中拔下的毒牙制成的武器。这毒牙即便在生物死亡后，仍旧保留着致命的毒性，其威力之残忍让人不寒而栗。为了将其制作为武器，工匠们采用了特殊的加工技术，并施加了各种保护措施。武器的鱼形设计正是这种特殊工艺的结晶。" },
  "The Prisoner Who Held Up Skies": { name: "支撑天空的罪犯", desc: "久远的过去，传说中的四个男人的故事。" },
  "The Queen's Platinum Staff": { name: "女王的白金法杖", desc: "传说中，永恒女王曾使用过的法杖。女王纯净而压倒性的魔力长期注入其中，使得其他人难以使用。但据说若由女王亲自使用，可完全释放其惊人的魔力。" },
  "The Red Horseman of War": { name: "战争的红骑士", desc: "四骑士将至，他们游历诸多世界，但不被欢迎。" },
  "The Seven Paragraphs of Love": { name: "七段的情书", desc: "在逆境中站起的两人结出爱情的果实。" },
  "The Seven-colored Dance": { name: "七彩的舞姿", desc: "在逆境中站起的两人结出爱情的果实。" },
  "The Seven-petaled Oath": { name: "七花瓣的誓言", desc: "在逆境中站起的两人结出爱情的果实。" },
  "The Sevenfold Testimony": { name: "七人的证词", desc: "在逆境中站起的两人结出爱情的果实。" },
  "The Severer of Fate": { name: "命运切割", desc: "历代玛格纳尔公爵登基时打造的名剑。这些剑通常形态相似，但每把都配备了与其主人魔力最匹配的魔法回路。据说，这些剑吸收了曾被其斩杀的敌人灵魂，可将敌人引向既定的命运之路。" },
  "The Silver Bough": { name: "银树枝", desc: "以分枝女神的分岔之路为灵感而打造的武器。\n这件武器起源于一位痴迷于分枝教团的铁匠所制作的小型象征物，作为献给女神的供奉。铁匠为了表达女神无限且多变的属性，在象征物的表面雕刻了各种装饰，最终将其打造成了一件附带多种刃状部件的钝器形武器。\n这件武器被赋予了女神的恩典。在诺克提斯发生的裂缝事件中，它曾被最勇敢的祭司们握在手中，用于对抗异物，在战斗中发挥了重要作用。" },
  "The Thousand Mile Needle": { name: "游走千里的针线", desc: "这世界交织成网，每根经纬都有其作用，通过这些作用彼此牵绊。" },
  "The Thousand Mile Warp": { name: "贯穿千里的经线", desc: "这世界交织成网，每根经纬都有其作用，通过这些作用彼此牵绊。" },
  "The Thousand Mile Weft": { name: "束缚千里的纬线", desc: "这世界交织成网，每根经纬都有其作用，通过这些作用彼此牵绊。" },
  "The Thousand Mile Yarn": { name: "编织千里的丝线", desc: "这世界交织成网，每根经纬都有其作用，通过这些作用彼此牵绊。" },
  "The Unbreakable Man": { name: "不折不扣的男子汉", desc: "久远的过去，传说中的四个男人的故事。" },
  "The White Horseman of Conquest": { name: "支配的白骑士", desc: "四骑士将至，他们游历诸多世界，但不被欢迎。" },
  "The Wings of Glory": { name: "荣耀之翼", desc: "这款步枪形态的执行工具融入了「枪灵的祝福」，具备增强超能力的功能，能够协助「子弹圣女」迅速且公正地执行判决。等待圣女审判的人遍布宇宙，法庭燃烧着渴望正义的热情。每当漫长的沉默后圣女的正义判决下达时，那震撼的枪响中蕴含着枪灵的气息，进一步激励了子弹圣女和枪械操作者的执行意志。" },
  "Thorned Brawler": { name: "荆棘斗士", desc: "他从未向人敞开心扉，直到遇见了温柔的她。" },
  "Thread of Ages": { name: "历史之结", desc: "以破碎的雷石碎片与父树的纤维，交织并系结历史的结而打造出的环刃。其力量之中蕴含著不可思议的神力，据说自极其久远的古代直到现今，所有沼泽精灵的历史都被记录其中。" },
  "Tideblossom": { name: "深潮之花", desc: "这是一把由声名远扬的女剑士——潘特莉的导师阿尔缇娅所传承的刺剑名刃。尽管曾在无数混战中取胜，其锋利的剑刃依旧如镜面般闪耀。虽鲜为人知，但其实是因为此剑蕴含了「随着战斗愈发锋利」的海之守护之力。宛如波纹流动般优雅而轻盈的剑身，使真正的使用者能施展既优雅又致命的技巧。" },
  "Tyrant Edge": { name: "暴君之刃", desc: "蓝沼湿地巡逻队传奇人物曾使用的武器的现代改良版。\n这款武器为优秀的蓝沼巡逻队军官量身定制。手柄由特殊的共鸣金属制成，能够有效传递空气的震动，让持有者提前感知攻击。刀刃经过魔法处理，可以在短时间内累积动量，从而大幅提升伤害。" },
  "Understanding Magic": { name: "魔力的理解", desc: "纯粹而原始的基础技巧，是踏上更高阶梯的基石。" },
  "Undying Flamefeather": { name: "不灭炎羽", desc: "正如古老典故所言，良禽择木而栖，慈爱而伟大的不死鸟血族也会慎重挑选作为巢穴的树木。这些即使死去也能再度归来的神秘而优雅的存在，会悉心照料自己选作栖身之所的树木。经过漫长岁月，与不死鸟血族一同成长的美丽树木逐渐吸收不死鸟的气息与魔力，最终成长为强大的魔力媒介。或许是长年相伴、悉心培育的缘故，受到不死鸟魔力滋养的树木会依照主人的意愿生长成形，如同第二颗心脏、魔力之核般发挥作用，并与主人缔结灵魂上的连结。这份连结甚至坚固到足以让彼此共同迎接复活的瞬间。就这样，手持专属于自己的树木——也就是被称为「火鸟木」的武器——现身战场的不死鸟，往往会化作焚尽战场一切的现象，如同毁灭本身般降临。而对这些将生与死视为一体、永恒存续的存在而言，这份珍宝也将永远伴随著他们，一同经历死亡与复活。" },
  "Unjust Hanging": { name: "冤枉的绞刑", desc: "世人嘲笑又何妨！这世界嘲笑我，不如自由地活着。" },
  "Vengeful Thornblade": { name: "报应的荆棘之刃", desc: "由无数荆棘构成的锐利刀刃，是战斗之痛的象征。修女骑士们在名为世界的斗争中，总是实时体验著痛苦的存在，并在其中成长。然而，有痛苦便有所得。战场上的痛苦越是剧烈，这把残酷却又美丽的剑，将赋予使用者越强大的力量与守护。" },
  "Vulkanus": { name: "布尔卡努斯", desc: "蕴含无尽热焰的布尔卡努斯如熔铁般熊熊燃烧，其炙热火焰从未熄灭。\n它诞生于古代锻造炉的锻铸之中，承载著被遗忘的火焰秘密，历经岁月仍未消逝。如今，它将在新生火焰的洗礼下再次重铸，将另一段神话铭刻于身躯之上。" },
  "Warmth of Dawn": { name: "黎明的温暖", desc: "黎明不是祝福。那是只会赐予「忍过黑暗之人」的约定。" },
  "Wellspring of Life": { name: "生命的源泉", desc: "以冰冷宇宙的温度加以温暖的，唯有奔驰于生命之中的存在…" },
  "Whisper of the River": { name: "流水低语", desc: "构成世界的四种物质，一切皆趋于调和。" },
  "Whispering Breeze": { name: "微风呢喃", desc: "要明确厘清精灵为何会寄宿于物品之中，并非易事。也许是被那蕴含强烈叙事与历史的物品力量所吸引而驻足，也可能只是单纯因为喜欢那件物品，便无意间栖息其中。无论如何，寄宿于物件的精灵往往在物质界中游荡、沉眠、观望世间；而有时，命运会引导他们遇见与自身波长契合的存在，并借出自己的力量。" },
  "Winner-Takes-All": { name: "一局定胜负", desc: "十年耻辱只为一战雪耻，磨骨削肉为之。" },
  "Wisdom of the Sun": { name: "太阳的智慧", desc: "即使是自行绽放光芒的太阳，起初也必然微弱。深知此理的小小火种静静燃烧著，等待著终将到来的炽烈之时。" },
  "Worn Anvil": { name: "古老的铁砧", desc: "成为匠人的方法很简单，坚持做自己喜欢的事。" },
  "Zamiel": { name: "扎米尔", desc: "扎米尔利用魔法能量增强其武器的火力，并受到奥尔克弹丸女祭司的祝福。\n这份祝福极大地提升了奥尔克射手的能力，使他们在战斗中更加致命。\n扎米尔的破坏力极强，以至于其射击常被误认为是魔法。" },
  "Zephyrus the Conceiver": { name: "孕育生命的西风", desc: "随风而行，小至种子，大至黑烟。" },
};

